class Solution:
    def splitArray(self, nums: List[int]) -> int:
        n = len(nums)
        isp = [False] * max(n, 2)
        if n > 2: isp[2:] = [True] * (n - 2)
        for i in range(2, int(n ** .5) + 1):
            if isp[i]:
                for j in range(i * i, n, i): isp[j] = False
        sa = sb = 0
        for i, x in enumerate(nums):
            if i < n and isp[i]: sa += x
            else: sb += x
        return abs(sa - sb)

