class Solution {
public:
    long long splitArray(vector<int>& nums) {
        int n = nums.size();
        vector<bool> isp(max(n, 2), false);
        for (int i = 2; i < n; i++) isp[i] = true;
        for (int i = 2; i * i < n; i++)
            if (isp[i]) for (int j = i * i; j < n; j += i) isp[j] = false;
        long long sa = 0, sb = 0;
        for (int i = 0; i < n; i++) (i >= 2 && isp[i] ? sa : sb) += nums[i];
        return llabs(sa - sb);
    }
};

