class Solution:
    def splitArray(self, nums: List[int]) -> int:
        def isp(i):
            if i < 2: return False
            d = 2
            while d * d <= i:
                if i % d == 0: return False
                d += 1
            return True
        sa = sb = 0
        for i, x in enumerate(nums):
            (sa, sb) = (sa + x, sb) if isp(i) else (sa, sb + x)
        return abs(sa - sb)

