class Solution {
    private boolean isp(int i) {
        if (i < 2) return false;
        for (int d = 2; (long) d * d <= i; d++) if (i % d == 0) return false;
        return true;
    }
    public long splitArray(int[] nums) {
        long sa = 0, sb = 0;
        for (int i = 0; i < nums.length; i++) { if (isp(i)) sa += nums[i]; else sb += nums[i]; }
        return Math.abs(sa - sb);
    }
}

